custom_css:
/*作者：lazyalie*/
/*作者有话说:禁二传二改商用。感谢帮助过我的老师们🥺🥺*/
/* 部分代码以及类名来自教程帖以及尾巴老师的拼好码，教程帖指路https://discord.com/channels/1291925535324110879/1380392618336194702;拼好码指路https://discord.com/channels/1291925535324110879/1422717884378910801 */
/* 部分素材来源花瓣网，插图来源画师：慕白 */



@import url("https://fontsapi.zeoseven.com/875/main/result.css");/* "ChillHuoSong_F" */
@import url("https://fontsapi.zeoseven.com/417/main/result.css");/* "TRW UDMincho" */





/* =====全局控制===== */
:root {
  --全局字体:"TRW UDMincho" ;
  --思维链字体:"ChillHuoSong_F" ; 
  --头像大小: 55cqw;
  --头像上下:3cqw;
  --头像左右:4.5%;
  --头像显示区域:center 10%; /*改数字调整头像到你想看到的部位，感谢咩野老师的代码*/
  --气泡间距: 70px;
  --气泡与输入框间距: 50px;
  --屏幕宽度: 1px;/* 数值越大越窄 */
  --输入框内文字: "月是千山燭，雪是萬斛隨珠";
  --思维链文字:  "人生三萬場倏忽，伴輿春茗細細讀";
  --名字字体大小: 3cqw;
  --crimson70a: transparent; 
  --black30a:transparent ;
}
/* =====全局控制结束===== */

body {
    font-family: var(--全局字体);
    font-weight: normal;
}



/* =====补丁部分===== */
div.inline-drawer-content {
  z-index: 2147483647 !important;
  position: relative !important; 
}

/*感谢咩野老师的全局阴影去除*/
body *:not(#send_form,.mes,q,textarea,input[type="number"],select,#user-settings-block h4,.standoutHeader,.completion_prompt_manager_prompt,img#avatar_load_preview,.menu_button,.mes .mes_block,input[type="checkbox"],#toast-container > .toast,code, pre code.hljs,.character_select.is_fav ,
.avatar-container.interactable.selected){
  box-shadow: none !important; 
  filter: none!important;
}

/*========文本调节========*/
.mes .mes_text {
    /* 字符间距  */
    letter-spacing: 1.8px; 
    /*  行间距   */
    line-height: 2 ; 
  text-align: justify !important;  
  width: 100%;
  padding-left: 1px;
  padding-right: 1px;
}
/* 每个段落开头缩进字符 */
p {
  text-indent: 0em; 

}
/*=====全局抽屉=====*/
  body.no-blur .drawer-content.openDrawer{
 background-image: url('https://iili.io/qV6Vg3l.png') !important;
  background-repeat: repeat-y !important;
  background-size: 100% auto !important;
  background-position: top center !important;
    padding: 10px;
    border-radius: none!important;
}
/*====顶栏====*/
#top-settings-holder {
    background: url('https://iili.io/qwoNHjs.png')!important;
    background-repeat: no-repeat;
    background-position: center 10%; 
    background-size: auto 100%; 
    position: relative;
}
#top-settings-holder .drawer-icon {
     opacity: 1!important; 
  content: url("https://iili.io/qhMPlgn.png");
  width: 30px;
  aspect-ratio: 1/1;  
   transform: rotate(34deg);
}
.drawer-icon.openIcon {
    transform: scale(1.3) !important;
    transition: all 0.2s ease !important;
}

/*====底栏====*/
 #send_form [class*="fa-"]{
  opacity: 1!important; 
  content: url("https://iili.io/qwcCDoN.png");
  width: 40px;
  aspect-ratio: 1/1;   
}
#leftSendForm .interactable,
#leftSendForm [class*="fa-"] {
    margin-right: -10px !important; 
}
i.fa-solid.fa-circle-stop {
  content: none!important;
}
/* 感谢nini老师分享的隐藏输入框小黑点 */
#send_textarea {
    resize: none !important;
}

/* 感谢墨千尾老师的输入框内文字自定义 */
#nonQRFormItems {
  position: relative;
}
#send_textarea::placeholder {
  color: rgba(0, 0, 0, 0) !important;
  text-shadow: none !important;
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: var(--输入框内文字);
  left: 50%;
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  color: var(--SmartThemeQuoteColor);
  font-style: normal;
  font-size: 0.5em;
  pointer-events: none;
  z-index: 10;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: calc(100% - 30px);
}
#send_textarea {
    border-radius: 0 !important; 
    padding: 1px;
    margin: 1px 1px;
  box-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3)!important;
}
/* 感谢nakari老师的悬浮底栏 */
#sheld, 
#chat {
    height: calc(102dvh + var(--bottomFormBlockSize));
    max-height: calc(102dvh + var(--bottomFormBlockSize));
}
#send_form { 
  background: url('https://iili.io/qwoNHjs.png')!important;
    background-repeat: no-repeat;
    background-position: center 10%; 
    background-size: auto 100%; 
    position: relative;   
    width: 95%;
    display: flex !important;
    align-items: center !important;
    padding: 2px 5px !important; 
    transition: all 0.3s ease;  
    border: 1px solid rgba(208, 208, 208, 1) !important; 
    outline: 2px solid #ffffff !important; 
    box-shadow: 0 0px 8px rgba(0, 0, 0, 0.17) !important;   
  border-radius: 0;  
}
/* 确保输入框固定在底部 */
#form_sheld {
    position: sticky;
    bottom: 70px;
    transition: transform 0.3s ease;
}
/* =====弹窗===== */
.dialog,
.popup,
.TH-popup .popup,
.vfm .popup {
        padding: 10px !important;
   border-radius: 0; 
}
/*消息弹窗*/
#toast-container > .toast {
    color:var(--main-text-color)!important;     
  background: #ffffff !important;
    border: 1px solid rgba(208, 208, 208, 1) !important; 
    outline: 2px solid #ffffff !important; 
    box-shadow: 0 0px 8px rgba(0, 0, 0, 0.17) !important; 
    padding: 13px 2px !important;    border-radius: 0;
}

#toast-container > .toast::before {
    content: '' !important;
    font-family: "Font Awesome 6 Free", "Segoe UI Symbol", sans-serif !important;
    font-weight: 900 !important;
    position: absolute !important;
    left: 15px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    font-size: 16px !important;
    color: var(--main-text-color) !important;
}

/* 成功弹窗 - 绿色对勾 */
#toast-container > .toast-success::before {
    content: "\f00c" !important; /* ✓ */
    color: rgba(124, 170, 79, 1) !important; 
}
/* 错误弹窗 - 红色叉号 */
#toast-container > .toast-error::before {
    content: "\f00d" !important; 
    color: rgba(152, 48, 48, 1) !important; 
}
/* 信息弹窗 - 蓝色i图标 */
#toast-container > .toast-info::before {
    content: "\f129" !important; 
    color: rgba(69, 126, 168, 1) !important; 
}

/* 警告弹窗 - 黄色感叹号 */
#toast-container > .toast-warning::before {
    content: "\f12a" !important; 
    color: rgba(200, 158, 87, 1) !important; 
}

#toast-container > .toast {
    padding-left: 45px !important; 
}


/* ====按钮图标类==== */
/* 基础样式 - 替换成古风符号 */
.inline-drawer-icon {
    font-size: 0 !important;  /* 隐藏原始图标 */
    position: relative !important;
    display: inline-block !important;
    width: 24px !important;  /* 根据你的符号大小调整 */
    height: 24px !important;
    transition: all 0.3s ease !important;
    cursor: pointer !important;
}

/* 用伪元素显示古风符号 */
.inline-drawer-icon::before {
    content: "◈" !important; 
   font-size: 20px !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    color: #63762F !important;  
    line-height: 1 !important;
    transition: all 0.3s ease !important;
}

.inline-drawer-icon:hover::before {
    transform: translate(-50%, -50%) scale(1.1) !important;
    filter: drop-shadow(0 0 4px #8fb78b) !important;
}
.qr--button,
.menu_button{
 background-color: rgba(255, 255, 255, 1)!important; 
    color: rgba(94, 106, 62, 1); 
    padding: 5px; 
    border: 1px solid rgba(223, 231, 192, 1); 
    box-shadow: 0 2px 3px rgba(0, 0, 0, 0.1); 
    font-size: 1em;
    transition: all 0.15s ease;
    border-radius: 0; 
}

.menu_button:hover {
    background-color: #e2dccb;    
    box-shadow: 0 3px 5px rgba(0, 0, 0, 0.15); 
    transform: translateY(-1px); 
}

.menu_button.redWarningBG,
.menu_button.red_button {
    color:  rgba(138, 48, 48, 1) !important;
}
.menu_button.world_set,
.menu_button.fav_on {
   color: rgba(169, 178, 58, 1) !important;
}
/*======复选框======*/
/* 复选框基础样式 */
input[type="checkbox"] {
    appearance: none !important;
    -webkit-appearance: none !important;
    width: 13px !important;
    height: 13px !important;
    background: #ffffff !important; 
    border: 1px solid #b5aa8e !important;  
    outline: 2px solid #ffffff !important;  
    box-shadow: 0 0 6px rgba(0, 0, 0, 0.5) !important; 
    border-radius: 0 !important; 
    cursor: pointer !important;
    position: relative !important;
    margin: 6px !important;
    padding: 0 !important;
    transition: all 0.2s ease !important;
}

/* 选中状态 */
input[type="checkbox"]:checked {
    background: rgba(182, 183, 139, 1) !important; 
    border-color: rgba(111, 105, 58, 1) !important;  
    outline-color: #ffffff !important; 
}
input[type="checkbox"]::before,
input[type="checkbox"]:checked::before {
    content: '' !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 100% !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

/*感谢nakari老师的防误触*/
@media screen and (max-width: 768px) {
  /* 禁用标签交互 */
  #user-settings-block .checkbox_label {
    pointer-events: none !important;
  }
  /* 恢复复选框交互 */
  #user-settings-block input[type="checkbox"] {
    pointer-events: auto !important;
  }
}
/* =====滚动条和滑动条=====*/
/* 隐藏所有滚动条 */
::-webkit-scrollbar {
  display: none !important;
}
/* Firefox */
* {
  scrollbar-width: none !important;
}
/* 滑动条 */
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 90%;
  height: 3px!important;
  background: linear-gradient(to right, rgba(190, 208, 160, 1), rgba(122, 139, 75, 1)) !important; 
  border-radius: 0;
  outline: none;
  margin: 10px 0;
}

/* 滑块按钮 */
input[type="range"]::-webkit-slider-thumb {
 -webkit-appearance: none;
  appearance: none;
  width: 28px;  
  height: auto; 
  aspect-ratio: 1 / 1; 
  background: url('https://iili.io/qhMPlgn.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  border: none;
  cursor: pointer;
  transform: rotate(-34deg);
}
input[type="range"]::-webkit-slider-thumb:hover {
  transform: scale(1.3);
}

/* ====角色和用户区域==== */
/* 感谢twelve老师的收藏区左右滑动 */
#HotSwapWrapper {
    overflow: hidden;
}
#HotSwapWrapper > div {
    display: flex;
    flex-wrap: nowrap;
    overflow-x: auto;
    overflow-y: hidden;
    height: calc(var(--avatar-base-height) + 10px);
    &::-webkit-scrollbar { height: 5px }
    &::-webkit-scrollbar-thumb {
        background: var(--ui-color-sec);
        border-radius: 5px;
    }
}
body.big-avatars #HotSwapWrapper > div {
    height: calc(var(--avatar-base-height) * var(--big-avatar-height-factor) + 10px);
}

.character_select.is_fav ,
.avatar-container.interactable.selected{
border: 1px solid rgba(188, 193, 166, 1);
box-shadow: 0 0 0 3px rgba(255, 255, 255, 1), 0 0 5px rgba(0, 0, 0, 0.58);
  border-radius: 0!important;
background-image: none!important;
 background-color: rgba(225, 230, 204, 1); 
color: rgba(99, 118, 47, 1);
}
.character_select.is_fav .avatar  {  
    margin: 0 !important;
    padding: 0 !important;       
    outline: none !important;  
}

.character_select.is_fav .ch_name {
color: var(--SmartThemeBorderColor)!important;
}


/*角色区域*/
/*布局灵感来自kakaa老师的双色盒子*/
/* 重新布局容器 */
#avatar_div.avatar_div.buttons_block.alignitemsflexstart.justifySpaceBetween.flexnowrap {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    position: relative !important;

}
/* 角色头像 */
img#avatar_load_preview {
    position: relative !important;
    margin: 0 !important;    
    width: 70% !important; 
  height: auto !important; 
  aspect-ratio: 1.7/ 1.1!important; 
    transform: rotate(0deg) !important;
  border: 1px solid rgba(96, 104, 82, 1) !important;   box-shadow: 0 0 0 3px rgba(255, 255, 255, 1), 0 0 5px rgba(0, 0, 0, 0.88);
  border-radius: 0;

 } 
#avatar_div.avatar_div.buttons_block.alignitemsflexstart.justifySpaceBetween.flexnowrap::after {
    content: "";
    position: absolute;
    top: -1cqw;
     left: -4cqw;
      width: 120%;  
  height: auto;
  aspect-ratio:190/108;
    background: url('https://iili.io/qhaKWZJ.png') center/contain no-repeat !important;
    transform: rotate(0deg);
    z-index: 100;
    pointer-events: none;
    filter: drop-shadow(2px 2px 3px rgba(0, 0, 0, 0.3));
}
/* 控制按钮 */
div#avatar_controls.flex-container {
    order: 2 !important;
    width: auto !important; 
    max-width: 100% !important;
    display: flex !important;
    justify-content: center !important;
    gap: 10px !important;
    margin: 1px auto !important; 
    position: relative !important;
    left: 0 !important;
    right: 0 !important;

}

/* =====预设部分===== */
ul#completion_prompt_manager_list.text_pole.ui-sortable {
    background: none!important;    
}
.completion_prompt_manager_prompt {
     background:rgba(225, 230, 204, 1); 
    border: 1px solid rgba(159, 165, 127, 1) !important; 
    outline: 2px solid #ffffff !important; 
    box-shadow: 0 0px 8px rgba(61, 69, 39, 0.3) !important; 
    color: rgba(68, 82, 11, 1);
   padding: 7px 32px !important;  
}
.prompt-manager-inspect-action{
color: rgba(69, 83, 9, 1)!important;
}
.completion_prompt_manager_prompt_disabled{ 
 background-color: rgba(255, 255, 255, 1)!important; 
}
/* =====七七八八框框===== */
.height100p.wide100p.maximized_textarea {
background:transparent;
}
textarea:not(.height100p.wide100p.maximized_textarea,.popup-input.text_pole.result-control.auto-select),
input[type="number"],
select{
 background: #ffffff !important;
    border: 1px solid rgba(208, 208, 208, 1) !important; 
    outline: 2px solid #ffffff !important; 
    box-shadow: 0 0px 8px rgba(0, 0, 0, 0.17) !important; 
    display: inline-block !important; 
    padding: 3px 2px !important; 
    margin: 5px 2px !important;
  border-radius: 0;
   text-align: center !important;       line-height: normal !important;     vertical-align: middle !important;  
}

.text_pole{
   background-color: rgba(240, 240, 221, 1);   
    border-radius: 0;
    color: rgba(70, 74, 25, 1);
    padding: 4px; 
}

.inline-drawer-header,
#user-settings-block h4,
.standoutHeader{
 position: relative;
border: 1px solid rgba(188, 193, 166, 1);
box-shadow: 0 0 0 3px rgba(255, 255, 255, 1), 0 0 5px rgba(0, 0, 0, 0.58);
  border-radius: 0!important;
background-image: none!important;
 background-color: rgba(225, 230, 204, 1); 
color: rgba(99, 118, 47, 1);
z-index: 1; 
  text-align: center !important;       line-height: normal !important;     vertical-align: middle !important;  
}

#user-settings-block h4 {
    position: relative; 
}

/* 展开框框 */
.inline-drawer-header{
 background-image: none!important;
  margin: 2px;
  padding: 6px  4px 6px 23px!important;

}
.world_entry .inline-drawer-header{
background: transparent!important;
  border: none!important;
}
/* 展开后 */
div.inline-drawer-content {  
  background-image: none!important;
  background-color: none!important;

}
　
/* 设置，菜单区域 */
#extensionsMenu{
border-radius: 0!important;
}
div#options.font-family-reset {
border-radius: 0!important;
}


/* ===对话区域=== */
/* 设置气泡整体布局 */
#chat{
background: none!important;
container-type: inline-size !important;
    container-name: chat !important;
  padding-bottom: var(--气泡与输入框间距);  padding-top: 20px!important;
}
.mes {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;     border-radius: 0 !important;
  border: none!important;
  margin-bottom: var(--气泡间距)!important;
  padding-bottom: 50px !important;
 margin-left: auto !important;  
    margin-right: auto !important;
  background-image: url('https://iili.io/qV6Vg3l.png') !important;
  background-repeat: repeat-y !important;
  background-size: 100% auto !important;
  background-position: top center !important;
  box-shadow: 0 0 0 1px #ccc, 0 0 0 4px #fff, 0 0 12px 0 rgba(0, 0, 0, 0.3) !important;
  width: calc(100% - var(--屏幕宽度)) !important; 
    max-width: none !important;
  box-sizing: border-box !important;
  position: relative !important;
}
.mes .mesAvatarWrapper {
   width: 100% !important;
    order: 1 !important;
    margin-bottom:  calc(var(--头像大小) * 0.83) !important;   
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: flex-start !important;
    gap: 1px !important;
  z-index: 65!important;

  }

/* 消息块置于下方并占满宽度 */
.mes .mes_block {
    order: 2 !important;
  padding: 1px 7px 25px 7px;  
    border-radius: 0px !important; 
    width: 102% !important;
    max-width: none !important; 
    margin-top: 0 !important; 
  overflow: visible !important;
  background-image: url('https://iili.io/qw3MAWG.png') !important;
  background-repeat: repeat-y !important;
  background-size: 100% auto !important;
  background-position: top center !important;
  box-shadow:  0 0 5px 0 rgba(0, 0, 0, 0.15) !important;
  z-index: 99;
}

/* 头像样式 */
.mes .avatar {  
  width: var(--头像大小) !important;
  height: calc(var(--头像大小) * 1/1.5) !important; 
  position: absolute;
  top: var(--头像上下);     
  left: var(--头像左右);    
  z-index: auto; 
  transform: none !important; 
  box-shadow: none!important;
  border: none!important;
}


.mes .avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover;
  border-radius: inherit;
  object-position: var(--头像显示区域);  
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.5) !important;
  border: none!important;

}

.mes .avatar::after {
  content: '';
  position: absolute;
  top: -3.7cqw;
  left: 1.5cqw;
  width: 192%;  
  height: auto;
  aspect-ratio:190/108;
  background-image: url('https://iili.io/qX5nyzP.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  pointer-events: none;
  transform: translateX(-10%); 
  }

/*感谢nakari老师分享的最后一条消息与下方区域距离保持一致代码*/
/* 通用CSS */
.mes .mes_timer:empty,
.mes .mesIDDisplay:empty,
.mes .tokenCounterDisplay:empty {
    display: none;
}
.last_mes .mesAvatarWrapper {
    padding-bottom: 0px; 
}

/* 三元素容器 */
.mes .mesAvatarWrapper .mesIDDisplay,
.mes .mesAvatarWrapper .mes_timer,
.mes .mesAvatarWrapper .tokenCounterDisplay {
  font-family: var(--思维链字体);
    position: relative!important;
    z-index: 35 !important;
    white-space: nowrap !important;
    font-size: 2cqw !important;
   top: calc(var(--头像大小) * 0.77) !important;
    left: calc(var(--头像大小) * 1.1) !important;
  padding: 0 0.8cqw !important;

}
.mes .mesAvatarWrapper .mes_timer,
.mes .mesAvatarWrapper .tokenCounterDisplay {
    border-left: 1px solid currentColor !important;
}
/* 感谢蘑菇老师的伪元素內元素居中代码 */
/* 名字 */
.name_text {
  font-family: var(--思维链字体);
    position: absolute !important;
    top: calc(var(--头像大小) * 0.82) !important;
    left:calc(var(--头像大小) * 0.56) !important; !important; 
  transform: translate(-50%, -50%) !important;  
    width: max-content !important;
       font-size: 3cqw !important;
  z-index: 78!important;  
}

/* 时间戳 */
.timestamp{
  font-family: var(--思维链字体);
    position: absolute !important;
    top: calc(var(--头像大小) * 0.175) !important;!important; 
    left: calc(var(--头像大小) * 0.91) !important;!important;
   width: 25%;
    text-align: center;
    white-space: nowrap !important;  
